            else:
                pixel_arrays.append(np.full(shape, pixel_slice))

        sliced_world_arrays = self._wcs.pixel_to_world_values(*pixel_arrays)
        if self._wcs.world_n_dim == 1:
            sliced_world_arrays = (sliced_world_arrays,)

        world_arrays_new = []
        iworld_curr = 0
        for iworld in range(self._wcs.world_n_dim):
            if iworld in self._world_keep:
                world_arrays_new.append(world_arrays[iworld_curr])
                iworld_curr += 1
            else:
                world_arrays_new.append(sliced_world_arrays[iworld])

        pixel_arrays = self._wcs.world_to_pixel_values(*world_arrays_new)
        if self._wcs.pixel_n_dim == 1:
            pixel_arrays = (pixel_arrays,)

        pixel_arrays_new = []
        for ipixel in self._pixel_keep:
            pixel_slice = self._slices_pixel[ipixel]
            start = pixel_slice.start or 0
            step = pixel_slice.step or 1
            pixel_arrays_new.append((pixel_arrays[ipixel] - start) / step)

        if self.pixel_n_dim == 1:
            return pixel_arrays_new[0]
        return tuple(pixel_arrays_new)

    cls.world_to_pixel_values = world_to_pixel_values
    return cls


