def _precomputed_cdf(self, x):
    from sympy import (Piecewise, S, Sum, asin, binomial, exp, factorial,
        floor, gamma, hyper, lowergamma, pi, sqrt, uppergamma)

    name = self.__class__.__name__

    if name == 'ArcsinDistribution':
        a, b = self.args
        value = 2*asin(sqrt((x - a)/(b - a)))/pi
        return Piecewise((S.Zero, x <= a), (S.One, x >= b), (value, True))

    if name == 'DagumDistribution':
        p, a, b = self.args
        return Piecewise((S.Zero, x <= 0),
                         ((1 + (x/b)**(-a))**(-p), True))

    if name == 'ErlangDistribution':
        k, rate = self.args
        return Piecewise((S.Zero, x < 0),
                         (lowergamma(k, rate*x)/gamma(k), True))

    if name == 'FrechetDistribution':
        a, scale, location = self.args
        value = exp(-((x - location)/scale)**(-a))
        return Piecewise((S.Zero, x <= location), (value, True))

    if name == 'GammaDistribution':
        k, theta = self.args
        return Piecewise((S.Zero, x < 0),
                         (lowergamma(k, x/theta)/gamma(k), True))

    if name == 'GammaInverseDistribution':
        a, b = self.args
        return Piecewise((S.Zero, x <= 0),
                         (uppergamma(a, b/x)/gamma(a), True))

    if name == 'KumaraswamyDistribution':
        a, b = self.args
        value = 1 - (1 - x**a)**b
        return Piecewise((S.Zero, x <= 0), (S.One, x >= 1),
                         (value, True))

    if name == 'LaplaceDistribution':
        mu, b = self.args
        return Piecewise((exp((x - mu)/b)/2, x < mu),
                         (1 - exp(-(x - mu)/b)/2, True))

    if name == 'LogisticDistribution':
        mu, scale = self.args
        return 1/(1 + exp(-(x - mu)/scale))

    if name == 'NakagamiDistribution':
        mu, omega = self.args
        return Piecewise((S.Zero, x < 0),
                         (lowergamma(mu, mu*x**2/omega)/gamma(mu), True))

    if name == 'StudentTDistribution':
        nu, = self.args
        value = (S.Half + x*gamma((nu + 1)/2)*
                 hyper((S.Half, (nu + 1)/2), (S(3)/2,), -x**2/nu)/
                 (sqrt(pi*nu)*gamma(nu/2)))
        return value

    if name == 'UniformSumDistribution':
        n, = self.args
        k = self._cdf_dummy
        value = Sum((-1)**k*binomial(n, k)*(x - k)**n,
                    (k, 0, floor(x)))/factorial(n)
        return Piecewise((S.Zero, x <= 0), (S.One, x >= n),
                         (value, True))


