def _preserve_unevaluated_relations(func):
    import ast
    from functools import wraps

    class Transformer(ast.NodeTransformer):
        relations = {
            ast.Eq: 'Eq', ast.NotEq: 'Ne',
            ast.Lt: 'Lt', ast.LtE: 'Le',
            ast.Gt: 'Gt', ast.GtE: 'Ge',
        }

        def visit_Compare(self, node):
            node = self.generic_visit(node)
            if not all(type(op) in self.relations for op in node.ops):
                return node
            operands = [node.left] + node.comparators
            relations = [
                ast.Call(
                    func=ast.Name(id=self.relations[type(op)], ctx=ast.Load()),
                    args=[operands[i], operands[i + 1]],
                    keywords=[ast.keyword(
                        arg='evaluate', value=ast.Constant(value=False))]
                )
                for i, op in enumerate(node.ops)
            ]
            if len(relations) == 1:
                return ast.copy_location(relations[0], node)
            return ast.copy_location(ast.Call(
                func=ast.Name(id='And', ctx=ast.Load()),
                args=relations,
                keywords=[ast.keyword(
                    arg='evaluate', value=ast.Constant(value=False))]
            ), node)

    @wraps(func)
    def wrapper(*args, **kwargs):
        evaluate = kwargs.get('evaluate', args[4] if len(args) > 4 else True)
        if not evaluate and args:
            try:
                tree = ast.parse(args[0], mode='eval')
                source = ast.unparse(ast.fix_missing_locations(
                    Transformer().visit(tree)))
                args = (source,) + args[1:]
            except (SyntaxError, TypeError, ValueError):
                pass
        return func(*args, **kwargs)

    return wrapper


